  const failed = sum(2)
  const skipped = sum(3)

  return { total: passed + failed + skipped, passed, failed, skipped, failures }
}

const go = (lines: readonly string[]): Tests | null => {
  const failures: TestFailure[] = []
  let passed = 0
  let skipped = 0

  lines.forEach((line, at) => {
    const found = /^\s*--- (FAIL|PASS|SKIP): (\S+) \(/.exec(line)

    if (found === null) {
      return
