      const said = /^\s+(\S+\.go):(\d+): (.+)$/
      const told = said.exec(lines[at + 1] ?? '') ?? said.exec(lines[at - 1] ?? '')
      failures.push({ name: found[2] ?? '', message: told?.[3] ?? '', file: told?.[1] ?? null, line: number(told?.[2]) })
    }
  })

